// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 1000, 700);

var SERIF = 'Georgia, "Times New Roman", serif';
var RED = '#cc2222', BLUE = '#1f5fd0';

/* ---------- text helpers ---------- */
function T(p, s, x, y, o) {
  o = o || {};
  var t = p.text(String(s));
  t.font({ family: SERIF, size: o.size || 15, style: (o.italic === false ? 'normal' : 'italic'), weight: o.weight || 'normal', anchor: 'middle' });
  t.fill(o.fill || '#000');
  if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.5, 'stroke-linejoin': 'round' });
  t.center(x, y);
  if (o.align === 'left') t.x(x);
  if (o.align === 'right') t.x(x - t.bbox().width);
  return t;
}
function mixed(p, parts, x, y, size) {
  var t = p.text(function (add) {
    parts.forEach(function (pt) { add.tspan(pt[0]).font({ style: pt[1] ? 'italic' : 'normal' }); });
  });
  t.font({ family: SERIF, size: size, anchor: 'middle' }).fill('#000');
  t.center(x, y);
  return t;
}
function angArc(g, ax, ay, gx, gy, r, color) {
  var th = Math.atan2(ay - gy, gx - ax);
  var x1 = ax + r, y1 = ay, x2 = ax + r * Math.cos(th), y2 = ay - r * Math.sin(th);
  g.path('M' + x1 + ' ' + y1 + ' A ' + r + ' ' + r + ' 0 0 0 ' + x2 + ' ' + y2)
    .fill('none').stroke({ color: color || '#000', width: 1.4 });
}
function hov(el, txt, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(txt, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  if (title) el.on('click', function () { showPopup(title, body); });
  return el;
}

/* ---------- groups ---------- */
var hiG = draw.group();
var panelsG = draw.group();
var liveG = draw.group();
var roG = draw.group();
var hotG = draw.group();

/* ================= reference panels ================= */
var panels = [
  {
    head: [['No triangle, ', 0], ['a', 1], [' < ', 0], ['h', 1]], tag: '(a)', kind: 'a',
    A: [18, 160], B: [155, 160], G: [126, 35],
    pop: ['Case (a): a < h', 'The side a hanging from γ is shorter than the altitude h = b·sin α, so its free end stops short of the base. A visible gap remains and no triangle can be closed.']
  },
  {
    head: [['Right triangle, ', 0], ['a', 1], [' = ', 0], ['h', 1]], tag: '(b)', kind: 'b',
    A: [18, 160], B: [155, 160], G: [155, 35],
    pop: ['Case (b): a = h', 'When a is exactly the altitude, it meets the base at one single point and does so perpendicularly. Exactly one triangle exists and it is a right triangle at β.']
  },
  {
    head: [['Two triangles, ', 0], ['a', 1], [' > ', 0], ['h', 1], [', ', 0], ['a', 1], [' < ', 0], ['b', 1]], tag: '(c)', kind: 'c',
    A: [10, 160], B: [205, 160], G: [143, 30],
    pop: ['Case (c): h < a < b', 'The arc of radius a now reaches past the base and cuts it in two places, one on each side of the altitude foot. Both dashed segments have the same length a, so two different triangles share the same α, a and b — the ambiguous case.']
  },
  {
    head: [['One triangle, ', 0], ['a', 1], [' ≥ ', 0], ['b', 1]], tag: '(d)', kind: 'd',
    A: [12, 160], B: [210, 160], G: [100, 44],
    pop: ['Case (d): a ≥ b', 'Once a is at least as long as b, the second intersection of the arc falls behind vertex α, off the usable ray. Only one triangle survives.']
  }
];
var hlRects = [];

panels.forEach(function (P, i) {
  var ox = i * 250 + 8, oy = 30;
  function X(v) { return ox + v; }
  function Y(v) { return oy + v; }
  var A = P.A, B = P.B, G = P.G;

  hlRects.push(hiG.rect(246, 238).move(ox - 6, 6).radius(10)
    .fill('#fff7cc').stroke({ color: '#e8b83a', width: 1.5 }).opacity(0));

  mixed(panelsG, P.head, ox + 118, 18, 15);
  panelsG.line(X(A[0]), Y(A[1]), X(B[0]), Y(B[1])).stroke({ color: '#000', width: 2 });
  panelsG.line(X(A[0]), Y(A[1]), X(G[0]), Y(G[1])).stroke({ color: '#000', width: 2 });
  angArc(panelsG, X(A[0]), Y(A[1]), X(G[0]), Y(G[1]), 30);

  if (P.kind === 'a') {
    panelsG.line(X(126), Y(35), X(126), Y(126)).stroke({ color: '#000', width: 2 });
    T(panelsG, 'a', X(140), Y(82), { size: 16, halo: true });
  } else if (P.kind === 'b') {
    panelsG.line(X(155), Y(35), X(155), Y(160)).stroke({ color: '#000', width: 2 });
    panelsG.path('M' + X(141) + ' ' + Y(160) + ' L ' + X(141) + ' ' + Y(146) + ' L ' + X(155) + ' ' + Y(146))
      .fill('none').stroke({ color: '#000', width: 1.4 });
    T(panelsG, 'a', X(170), Y(95), { size: 16, halo: true });
  } else if (P.kind === 'c') {
    panelsG.line(X(143), Y(30), X(143), Y(160)).stroke({ color: '#000', width: 2 });
    panelsG.line(X(143), Y(30), X(81), Y(160)).stroke({ color: '#000', width: 2, dasharray: '7,5' });
    panelsG.line(X(143), Y(30), X(205), Y(160)).stroke({ color: '#000', width: 2, dasharray: '7,5' });
    T(panelsG, 'a', X(106), Y(92), { size: 16, halo: true });
    T(panelsG, 'a', X(185), Y(92), { size: 16, halo: true });
    T(panelsG, 'h', X(155), Y(116), { size: 16, halo: true });
  } else {
    panelsG.line(X(G[0]), Y(G[1]), X(B[0]), Y(B[1])).stroke({ color: '#000', width: 2 });
    T(panelsG, 'a', X((G[0] + B[0]) / 2 + 14), Y((G[1] + B[1]) / 2 - 2), { size: 16, halo: true });
  }

  T(panelsG, 'α', X(A[0]) - 13, Y(A[1]) + 8, { size: 16, halo: true });
  T(panelsG, 'β', X(B[0]) + 13, Y(B[1]) + 8, { size: 16, halo: true });
  T(panelsG, 'γ', X(G[0]), Y(G[1]) - 14, { size: 16, halo: true });
  T(panelsG, 'b', X((A[0] + G[0]) / 2) - 14, Y((A[1] + G[1]) / 2), { size: 16, halo: true });
  T(panelsG, P.tag, ox + 118, oy + 202, { size: 15, italic: false });

  var hot = hotG.rect(246, 238).move(ox - 6, 6).fill('#fff').opacity(0);
  hov(hot, P.pop[0], P.pop[0], P.pop[1]);
});

/* ================= live construction ================= */
var Ax = 70, Ay = 630, s = 52, alpha = 35 * Math.PI / 180, bLen = 5;
var hLen = bLen * Math.sin(alpha);
var Gx = Ax + bLen * Math.cos(alpha) * s, Gy = Ay - bLen * Math.sin(alpha) * s;

var S = { a: 2, showAlt: true };
var caseIdx = 0;
var caseVals = [2, 2.9, 4, 5.5];
var caseNames = ['a < h (no triangle)', 'a = h (right triangle)', 'h < a < b (two triangles)', 'a ≥ b (one triangle)'];

function caseOf(a) {
  if (a < hLen - 0.06) return 0;
  if (Math.abs(a - hLen) <= 0.06) return 1;
  if (a < bLen - 0.04) return 2;
  return 3;
}

function renderLive() {
  liveG.clear();
  var ci = caseOf(S.a);
  var a = (ci === 1) ? hLen : S.a;
  var r = a * s;

  /* given parts */
  var base = liveG.line(50, Ay, 720, Ay).stroke({ color: '#000', width: 2.2 });
  hov(base, 'Base ray from α — fixed', 'The given parts', 'Angle α and side b are given and never change. Only the length of the swinging side a is unknown, and it alone decides how many triangles can close.');
  var bl = liveG.line(Ax, Ay, Gx, Gy).stroke({ color: '#000', width: 2.6 });
  hov(bl, 'Side b = 5 (given) — fixes vertex γ', 'Side b', 'Side b runs from α at the given angle of 35°, so vertex γ is completely determined before a is chosen.');
  angArc(liveG, Ax, Ay, Gx, Gy, 50);
  T(liveG, 'α', Ax - 17, Ay + 10, { size: 18, halo: true });
  T(liveG, 'γ', Gx, Gy - 18, { size: 18, halo: true });
  T(liveG, 'b', 164, 538, { size: 18, halo: true });

  /* altitude */
  if (S.showAlt) {
    var alt = liveG.line(Gx, Gy, Gx, Ay).stroke({ color: BLUE, width: 2, dasharray: '7,5' });
    hov(alt, 'h = b·sin α ≈ 2.87 — shortest reach from γ', 'The altitude h',
      'The perpendicular distance from γ to the base is h = b·sin α ≈ 2.87. No segment from γ can be shorter than h and still touch the base, which is why a < h gives no triangle at all.');
    T(liveG, 'h', Gx - 18, (Gy + Ay) / 2, { size: 18, fill: BLUE, halo: true });
    liveG.line(Gx - 6, Ay, Gx + 6, Ay).stroke({ color: BLUE, width: 2.5 });
    if (ci === 1) {
      liveG.path('M' + (Gx - 16) + ' ' + Ay + ' L ' + (Gx - 16) + ' ' + (Ay - 16) + ' L ' + Gx + ' ' + (Ay - 16))
        .fill('none').stroke({ color: BLUE, width: 1.6 });
    }
  }

  /* intersections */
  var pts = [], d = 0;
  if (Math.abs(a - hLen) < 1e-9) { pts = [Gx]; }
  else if (a > hLen) {
    d = Math.sqrt(a * a - hLen * hLen) * s;
    if (Gx - d > Ax + 2) pts.push(Gx - d);
    pts.push(Gx + d);
  }

  /* triangles */
  pts.forEach(function (px) {
    liveG.polygon([[Ax, Ay], [px, Ay], [Gx, Gy]].map(function (p) { return p.join(','); }).join(' '))
      .fill({ color: RED, opacity: 0.10 }).stroke('none');
  });

  /* compass arc */
  var segs = [], cur = [];
  for (var i = 0; i <= 240; i++) {
    var th = (190 + (350 - 190) * i / 240) * Math.PI / 180;
    var x = Gx + r * Math.cos(th), y = Gy - r * Math.sin(th);
    if (y <= Ay + 0.5) cur.push([x, y]);
    else { if (cur.length > 1) segs.push(cur); cur = []; }
  }
  if (cur.length > 1) segs.push(cur);
  segs.forEach(function (sg) {
    var pl = liveG.polyline(sg.map(function (p) { return p[0].toFixed(1) + ',' + p[1].toFixed(1); }).join(' '))
      .fill('none').stroke({ color: RED, width: 1.6, dasharray: '5,4', opacity: 0.85 });
    hov(pl, 'Compass arc of radius a = ' + a.toFixed(2) + ' centred at γ', 'The swinging side a',
      'Think of side a as a compass needle pinned at γ. Every point of this red arc is a possible landing spot; a triangle exists only where the arc actually meets the base ray.');
  });

  /* side a segments + labels */
  if (pts.length === 0) {
    var tipY = Gy + r;
    liveG.line(Gx, Gy, Gx, tipY).stroke({ color: RED, width: 2.8 });
    liveG.circle(12).center(Gx, tipY).fill('#fff').stroke({ color: RED, width: 2.5 });
    T(liveG, 'a', Gx + 18, (Gy + tipY) / 2, { size: 18, fill: RED, halo: true });
    var gap = liveG.rect(26, Math.max(4, Ay - tipY)).move(Gx - 13, tipY).fill('#fff').opacity(0);
    hov(gap, 'Gap: a is too short to reach the base', 'No triangle',
      'Because a < h the free end of a stops above the base line. The gap you see here is exactly what panel (a) of the textbook figure shows.');
  } else {
    pts.forEach(function (px, k) {
      var seg = liveG.line(Gx, Gy, px, Ay).stroke({ color: RED, width: 2.8 });
      hov(seg, 'Side a = ' + a.toFixed(2) + ' closing the triangle', 'A closing side a',
        'This red segment has length a and joins γ to the base, closing a triangle with the given α and b. Its foot is the vertex β of that solution.');
      liveG.circle(13).center(px, Ay).fill('#fff').stroke({ color: RED, width: 2.5 });
      var mx = (Gx + px) / 2, my = (Gy + Ay) / 2;
      var off = (px < Gx - 1) ? -20 : (pts.length === 1 && Math.abs(px - Gx) < 1 ? 20 : 20);
      T(liveG, 'a', mx + off, my - 4, { size: 18, fill: RED, halo: true });
      var bl2 = (pts.length === 2) ? (k === 0 ? 'β₁' : 'β₂') : 'β';
      T(liveG, bl2, px, Ay + 20, { size: 18, halo: true });
    });
  }

  renderReadout(a, pts.length);
  hlRects.forEach(function (h, i) { h.opacity(i === ci ? 1 : 0); });
  var cl = document.getElementById('caseStateLabel');
  if (cl) cl.textContent = 'current: ' + caseNames[ci] + ' → ' + pts.length + ' triangle' + (pts.length === 1 ? '' : 's');
}

function renderReadout(a, count) {
  roG.clear();
  roG.rect(288, 110).move(700, 288).radius(8).fill('#ffffff').stroke({ color: '#c8ccd2', width: 1 });
  T(roG, 'a = ' + a.toFixed(2), 716, 310, { size: 15, align: 'left' });
  T(roG, 'h = b · sin α = ' + hLen.toFixed(2), 716, 332, { size: 15, align: 'left' });
  T(roG, 'b = 5.00', 716, 354, { size: 15, align: 'left' });
  T(roG, 'triangles: ' + count, 716, 380, { size: 16, italic: false, weight: 'bold', fill: RED, align: 'left' });

  roG.rect(288, 100).move(700, 420).radius(8).fill('#fcfcfd').stroke({ color: '#e0e3e7', width: 1 });
  roG.line(714, 444, 748, 444).stroke({ color: '#000', width: 2.4 });
  T(roG, 'given parts (α, b, base)', 756, 444, { size: 13, italic: false, align: 'left' });
  roG.line(714, 470, 748, 470).stroke({ color: RED, width: 2.8 });
  T(roG, 'swinging side a (dashed = its arc)', 756, 470, { size: 13, italic: false, align: 'left' });
  roG.line(714, 496, 748, 496).stroke({ color: BLUE, width: 2, dasharray: '7,5' });
  T(roG, 'altitude h = b · sin α', 756, 496, { size: 13, italic: false, align: 'left' });
}

/* ================= controls ================= */
function update_lengthA(v) { S.a = v; renderLive(); }
function toggle_showAltitude(on) { S.showAlt = on; renderLive(); }
function setA(v) {
  var inp = document.getElementById('lengthAInput');
  inp.value = v;
  document.getElementById('lengthAVal').value = (+v).toFixed(1);
  S.a = +v;
}
function setAlt(on) {
  document.getElementById('showAltitudeInput').checked = on;
  S.showAlt = on;
}
function trigger_caseStep() {
  caseIdx = (caseIdx + 1) % 4;
  setA(caseVals[caseIdx]);
  renderLive();
}

/* ================= demo steps ================= */
var steps = [
  { title: 'The fixed given parts', n: 'Angle α and side b are locked in place, so vertex γ never moves; only the length of side a is unknown. The dashed altitude h drops from γ perpendicular to the base and marks the shortest distance γ can ever reach.', st: { a: 2, alt: true, c: 0 } },
  { title: 'Case (a): a is too short', n: 'With a = 2.0 and h ≈ 2.87, the arc of radius a swung from γ never reaches the base — a visible gap remains, exactly as in panel (a). No triangle can close.', st: { a: 2, alt: true, c: 0 } },
  { title: 'Case (b): a exactly equals h', n: 'Grow a to 2.87 and the arc just grazes the base at a single point, landing perpendicularly at β. The right-angle square appears: exactly one triangle, and it is a right triangle.', st: { a: 2.9, alt: true, c: 1 } },
  { title: 'Case (c): the ambiguous case', n: 'For a between h and b, the arc crosses the base in two places, giving two different closing segments — the two dashed sides a of panel (c). Both are valid triangles with the same α, a, and b.', st: { a: 4, alt: true, c: 2 } },
  { title: 'Case (d): a overtakes b', n: 'Once a reaches or passes b, the second intersection falls on the wrong side of α — behind the vertex — so only one triangle survives. Turn the altitude off and the sketch is just the ordinary triangle of panel (d).', st: { a: 5.5, alt: false, c: 3 } }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  var S2 = steps[stepIdx];
  setA(S2.st.a);
  setAlt(S2.st.alt);
  caseIdx = S2.st.c;
  document.getElementById('stepTitle').textContent = S2.title;
  document.getElementById('demoNarration').textContent = S2.n;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + ' / ' + steps.length;
  renderLive();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

