  T(g, 'β', X(B[0] + 13), Y(B[1] + 9), { size: 16 });
  T(g, 'γ', X(G[0]), Y(G[1] - 15), { size: 16 });
  T(g, 'b', X((A[0] + G[0]) / 2 - 14), Y((A[1] + G[1]) / 2 - 5), { size: 16 });
  T(g, P.tag, X((A[0] + B[0]) / 2), Y(196), { size: 15, roman: true });

