function renderCases() {
  var grid = (VW / VH) < 2.0;
  var cols = grid ? 2 : 4, rows = grid ? 2 : 1;
  var cellW = VW / cols, cellH = VH / rows;
  var k = Math.min(cellW * 0.93 / BOXW, cellH * 0.90 / BOXH);
  var ci = caseOf(S.a);
  panels.forEach(function (P, i) {
    var c = i % cols, r = Math.floor(i / cols);
    var tx = c * cellW + (cellW - BOXW * k) / 2;
    var ty = r * cellH + (cellH - BOXH * k) / 2;
