  if (S.view === 'cases') renderCases(); else renderLive();
  var bc = document.getElementById('viewCasesBtn'), bv = document.getElementById('viewLiveBtn');
  if (bc) bc.classList.toggle('active', S.view === 'cases');
  if (bv) bv.classList.toggle('active', S.view === 'live');
}

document.addEventListener('fig-resize', function (e) {
  updateViewbox(e.detail.width, e.detail.height);
  render();
});

/* ================= controls ================= */
function setView(v) { S.view = v; render(); }
function update_lengthA(v) { S.a = v; S.view = 'live'; render(); }
function toggle_showAltitude(on) { S.alt = on; render(); }

function setA(v) {
  var inp = document.getElementById('lengthAInput');
  if (inp) { inp.value = v; document.getElementById('lengthAVal').value = (+v).toFixed(1); }
  S.a = +v;
}
function setAlt(on) {
  var c = document.getElementById('showAltitudeInput');
  if (c) c.checked = on;
  S.alt = on;
}

/* ================= demo steps ================= */
var steps = [
  {
    title: 'What is given',
    n: 'Angle α and side b are known, so the apex γ is already pinned down; only the length of side a is free. These four textbook panels show every outcome — press ▶ (or drag the slider) to build them yourself with a compass arc.',
    a: 4, alt: true, view: 'cases'
  },
  {
    title: 'a shorter than h — no triangle',
    n: 'When a is shorter than the altitude h = b·sin α, the arc swung from γ stops above the base and a visible gap remains. No triangle can close, so the given parts describe no triangle at all.',
    a: 3, alt: true, view: 'live'
  },
  {
    title: 'a equal to h — one right triangle',
    n: 'Grow a until it just equals h and the arc grazes the base at a single point, meeting it perpendicularly. Exactly one triangle exists, and it is a right triangle.',
    a: 5.7, alt: true, view: 'live'
  },
  {
    title: 'h < a < b — the ambiguous case',
    n: 'For lengths between h and b the arc cuts the base in two places, so two different triangles share the same α, a and b. The dashed side a lands at the alternate vertex β′. This is the ambiguous SSA case.',
    a: 7, alt: true, view: 'live'
  },
  {
    title: 'a at least b — one triangle',
    n: 'Once a reaches or exceeds b the second intersection falls behind the vertex at α, off the usable ray, so only one triangle survives.',
    a: 11, alt: false, view: 'live'
  }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  var st = steps[stepIdx];
  setA(st.a);
  setAlt(st.alt);
  S.view = st.view;
  document.getElementById('stepTitle').textContent = st.title;
  document.getElementById('demoNarration').textContent = st.n;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + ' / ' + steps.length;
  render();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

updateViewbox();
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
