// @FIGURE_CODE_BEGIN
var container = document.getElementById('container');
var draw = SVG().addTo(container).size('100%', '100%');

var SERIF = 'Georgia, "Times New Roman", serif';
var INK = '#111', ACC = '#c62828', ALTC = '#6b87a8';
var VW = 1000, VH = 700;

var casesG = draw.group();
var liveG = draw.group();

/* ---------------- text helpers ---------------- */
function T(p, s, x, y, o) {
  o = o || {};
  var t = p.text(String(s));
  t.font({
    family: SERIF, size: o.size || 17,
    style: (o.roman ? 'normal' : 'italic'),
    weight: o.weight || 'normal', anchor: 'middle'
  });
  t.fill(o.fill || INK);
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': o.haloW || 3.2, 'stroke-linejoin': 'round' });
  t.center(x, y);
  return t;
}
function mixed(p, parts, x, y, size, fill) {
  var t = p.text(function (add) {
    parts.forEach(function (q) { add.tspan(q[0]).font({ style: q[1] ? 'italic' : 'normal' }); });
  });
  t.font({ family: SERIF, size: size, anchor: 'middle' }).fill(fill || INK);
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.2, 'stroke-linejoin': 'round' });
  t.center(x, y);
  return t;
}
function angArc(g, ax, ay, gx, gy, r, color, w) {
  var th = Math.atan2(ay - gy, gx - ax);
  var x1 = ax + r, y1 = ay, x2 = ax + r * Math.cos(th), y2 = ay - r * Math.sin(th);
  g.path('M' + x1 + ' ' + y1 + ' A ' + r + ' ' + r + ' 0 0 0 ' + x2 + ' ' + y2)
    .fill('none').stroke({ color: color || INK, width: w || 1.5 });
}
function hov(el, txt, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(txt, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  if (title) el.on('click', function () { showPopup(title, body); });
  return el;
}

/* ---------------- geometry constants ---------------- */
var ALPHA = 35 * Math.PI / 180, BLEN = 10;
var HLEN = BLEN * Math.sin(ALPHA);          /* ≈ 5.74 */
var GXW = BLEN * Math.cos(ALPHA), GYW = HLEN;

var S = { a: 4, alt: true, view: 'cases' };

function caseOf(a) {
  if (a < HLEN - 0.05) return 0;
  if (Math.abs(a - HLEN) <= 0.05) return 1;
  if (a < BLEN - 0.03) return 2;
  return 3;
}

/* ================= four textbook panels (single strip) ================= */
var PH = 250;                                /* local panel height */

var panels = [
  {
    kind: 'a', tag: '(a)', w: 186, idx: 0,
    head: [['No triangle, ', 0], ['a', 1], [' < ', 0], ['h', 1]],
    A: [22, 194], B: [160, 194], G: [130, 66],
    pop: ['Case (a): a < h',
      'The side a swung down from γ is shorter than the altitude h = b·sin α, so its free end stops above the base. A gap remains and no triangle can be closed.']
  },
  {
    kind: 'b', tag: '(b)', w: 192, idx: 1,
    head: [['Right triangle, ', 0], ['a', 1], [' = ', 0], ['h', 1]],
    A: [22, 194], B: [162, 194], G: [162, 66],
    pop: ['Case (b): a = h',
      'When a is exactly the altitude it reaches the base at one single point, and it meets it perpendicularly. Exactly one triangle exists and it is a right triangle at β.']
  },
  {
    kind: 'c', tag: '(c)', w: 258, idx: 2,
    head: [['Two triangles, ', 0], ['a', 1], [' > ', 0], ['h', 1], [', ', 0], ['a', 1], [' < ', 0], ['b', 1]],
    A: [18, 194], B: [232, 194], G: [158, 62],
    pop: ['Case (c): h < a < b — the ambiguous case',
      'The arc of radius a now reaches past the base and cuts it in two places, one on each side of the altitude foot. Both dashed segments have length a, so two different triangles share the same α, a and b.']
  },
  {
    kind: 'd', tag: '(d)', w: 252, idx: 3,
    head: [['One triangle, ', 0], ['a', 1], [' ≥ ', 0], ['b', 1]],
    A: [14, 194], B: [234, 194], G: [120, 72],
    pop: ['Case (d): a ≥ b',
      'Once a is at least as long as b, the second intersection of the arc falls behind the vertex at α, off the usable ray. Only one triangle survives.']
  }
];

function drawPanel(g, P, active) {
  var A = P.A, B = P.B, G = P.G, w = P.w;

  var head = mixed(g, P.head, w / 2, 20, 16);
  if (active) {
    var bb = head.bbox();
    g.line(bb.x + 2, 33, bb.x2 - 2, 33).stroke({ color: ACC, width: 1.6, linecap: 'round' }).opacity(0.85);
  }

  g.line(A[0], A[1], B[0], B[1]).stroke({ color: INK, width: 2.3 });
  g.line(A[0], A[1], G[0], G[1]).stroke({ color: INK, width: 2.3 });
  angArc(g, A[0], A[1], G[0], G[1], 32);

  if (P.kind === 'a') {
    g.line(130, 66, 130, 170).stroke({ color: INK, width: 2.3 });
    T(g, 'a', 147, 118, { size: 17 });
    T(g, 'b', 60, 116, { size: 17 });
  } else if (P.kind === 'b') {
    g.line(162, 66, 162, 194).stroke({ color: INK, width: 2.3 });
    g.path('M146 194 L 146 178 L 162 178').fill('none').stroke({ color: INK, width: 1.5 });
    T(g, 'a', 179, 120, { size: 17 });
    T(g, 'b', 78, 116, { size: 17 });
  } else if (P.kind === 'c') {
    if (S.alt) {
      g.line(158, 62, 158, 194).stroke({ color: INK, width: 2.3 });
      T(g, 'h', 172, 158, { size: 17 });
    }
    g.line(158, 62, 92, 194).stroke({ color: INK, width: 2.3, dasharray: '8,6' });
    g.line(158, 62, 232, 194).stroke({ color: INK, width: 2.3, dasharray: '8,6' });
    T(g, 'a', 104, 137, { size: 17 });
    T(g, 'a', 210, 121, { size: 17 });
    T(g, 'b', 70, 114, { size: 17 });
  } else {
    g.line(G[0], G[1], B[0], B[1]).stroke({ color: INK, width: 2.3 });
    T(g, 'a', 194, 122, { size: 17 });
    T(g, 'b', 52, 122, { size: 17 });
  }

  T(g, 'α', A[0] - 14, A[1] + 12, { size: 17 });
  T(g, 'β', B[0] + 14, B[1] + 12, { size: 17 });
  T(g, 'γ', G[0], G[1] - 16, { size: 17 });
  T(g, P.tag, w / 2, 234, { size: 16, roman: true });

  var hot = g.rect(w + 16, PH).move(-8, 0).fill('#fff').opacity(0.001);
  hov(hot, P.pop[0], P.pop[0], P.pop[1]);
}

function renderCases() {
  var gap = 22;
  var cols = ((VW / VH) >= 0.8) ? 4 : 2;      /* prefer the 1×4 source strip */
  var rows = [];
  for (var i = 0; i < panels.length; i += cols) rows.push(panels.slice(i, i + cols));
  var rowW = rows.map(function (r) {
    return r.reduce(function (s, p) { return s + p.w; }, 0) + gap * (r.length - 1);
  });
  var maxW = Math.max.apply(null, rowW);
  var k = Math.min(VW * 0.97 / maxW, (VH * 0.93 / rows.length) / PH);
  var totalH = rows.length * PH * k;
  var y0 = (VH - totalH) / 2;
  var ci = caseOf(S.a);
  rows.forEach(function (r, ri) {
    var x = (VW - rowW[ri] * k) / 2;
    r.forEach(function (P) {
      var g = casesG.group().attr('transform',
        'translate(' + x.toFixed(2) + ',' + (y0 + ri * PH * k).toFixed(2) + ') scale(' + k.toFixed(4) + ')');
      drawPanel(g, P, P.idx === ci);
      x += (P.w + gap) * k;
    });
  });
}

/* ================= live compass construction ================= */
function renderLive() {
  var ci = caseOf(S.a);
  var a = (ci === 1) ? HLEN : S.a;

  var capH = 62, mg = 30;
  var availW = VW - 2 * mg, availH = VH - 2 * mg - capH;
  var s = Math.min(availW / 22.6, availH / 7.6, 92);
  var x0 = mg + (availW - 22.6 * s) / 2 + 1.3 * s;
  var yB = mg + (availH - 7.6 * s) / 2 + 6.5 * s;
  function WX(u) { return x0 + u * s; }
  function WY(v) { return yB - v * s; }
  var LBL = Math.max(17, 0.56 * s);

  var Gx = WX(GXW), Gy = WY(GYW), Ax = WX(0), Ay = WY(0);

  var xs = [];
  if (Math.abs(a - HLEN) < 1e-9) { xs = [GXW]; }
  else if (a > HLEN) {
    var d = Math.sqrt(a * a - HLEN * HLEN);
    if (GXW - d > 0.02) xs.push(GXW - d);
    xs.push(GXW + d);
  }

  xs.forEach(function (ux) {
    liveG.polygon([[Ax, Ay], [WX(ux), Ay], [Gx, Gy]].map(function (p) {
      return p[0].toFixed(1) + ',' + p[1].toFixed(1);
    }).join(' ')).fill({ color: ACC, opacity: 0.09 }).stroke('none');
  });

  var base = liveG.line(WX(-0.4), Ay, WX(21.2), Ay).stroke({ color: INK, width: 2.4 });
  hov(base, 'Base ray from α (given direction)', 'The given parts',
    'Angle α and side b are given, so the apex γ is pinned down before anything else. Only the length of the swinging side a is free, and it alone decides how many triangles can close.');

  /* compass arc of radius a, centred at γ */
  var segs = [], cur = [];
  for (var i = 0; i <= 280; i++) {
    var th = Math.PI + Math.PI * (i / 280);
    var wx = GXW + a * Math.cos(th), wy = GYW + a * Math.sin(th);
    if (wy >= -0.02 && wx >= -0.4) cur.push([WX(wx), WY(wy)]);
    else { if (cur.length > 1) segs.push(cur); cur = []; }
  }
  if (cur.length > 1) segs.push(cur);
  segs.forEach(function (sg) {
    var pl = liveG.polyline(sg.map(function (p) { return p[0].toFixed(1) + ',' + p[1].toFixed(1); }).join(' '))
      .fill('none').stroke({ color: ACC, width: 1.7, dasharray: '6,5', opacity: 0.9 });
    hov(pl, 'Compass arc of radius a = ' + a.toFixed(2) + ', centred at γ', 'Side a as a compass arc',
      'Side a is a compass needle pinned at γ: every point of this arc is a possible landing spot for its free end. A triangle exists exactly where the arc meets the base ray.');
  });

  var bl = liveG.line(Ax, Ay, Gx, Gy).stroke({ color: INK, width: 2.6 });
  hov(bl, 'Side b = 10 (given) — fixes vertex γ', 'Side b',
    'Side b leaves α at the given angle of 35°, so vertex γ is completely determined before a is chosen. Nothing about b or α changes as you drag the slider.');
  angArc(liveG, Ax, Ay, Gx, Gy, 0.95 * s, INK, 1.8);

  if (S.alt) {
    var alt = liveG.line(Gx, Gy, Gx, Ay).stroke({ color: ALTC, width: 2, dasharray: '7,5' });
    hov(alt, 'h = b·sin α ≈ ' + HLEN.toFixed(2) + ' — the shortest reach from γ', 'The altitude h',
      'The perpendicular distance from γ to the base is h = b·sin α. No segment from γ can be shorter than h and still touch the base, which is why a < h gives no triangle at all.');
    liveG.path('M' + (Gx - 0.34 * s) + ' ' + Ay + ' L ' + (Gx - 0.34 * s) + ' ' + (Ay - 0.34 * s) + ' L ' + Gx + ' ' + (Ay - 0.34 * s))
      .fill('none').stroke({ color: ALTC, width: 1.6 });
    T(liveG, 'h', Gx - 0.48 * s, (Gy + Ay) / 2, { size: LBL, fill: ALTC });
  }

  if (xs.length === 0) {
    var tipY = WY(GYW - a);
    var seg0 = liveG.line(Gx, Gy, Gx, tipY).stroke({ color: ACC, width: 3 });
    hov(seg0, 'Side a = ' + a.toFixed(2) + ' — too short to reach the base', 'No triangle',
      'Even hanging straight down (its closest possible approach) the side a stops above the base. The gap you see is exactly what panel (a) of the textbook figure shows.');
    liveG.circle(0.3 * s).center(Gx, tipY).fill('#fff').stroke({ color: ACC, width: 2.4 });
    T(liveG, 'a', Gx + 0.52 * s, (Gy + tipY) / 2, { size: LBL, fill: ACC });
  } else {
    xs.forEach(function (ux, k) {
      var px = WX(ux);
      var two = (xs.length === 2);
      var isLeft = two && k === 0;
      var seg = liveG.line(Gx, Gy, px, Ay)
        .stroke({ color: ACC, width: 3, dasharray: isLeft ? '9,6' : null });
      hov(seg, 'Side a = ' + a.toFixed(2) + (isLeft ? ' (second solution)' : ''),
        isLeft ? 'The second triangle' : 'A closing side a',
        isLeft
          ? 'This dashed segment also has length a and also closes a triangle with the same α and b — its foot is the alternate vertex β′. Two different triangles fit the same SSA data.'
          : 'This segment has length a and joins γ to the base, closing a triangle with the given α and b. Its foot is the vertex β.');
      liveG.circle(0.32 * s).center(px, Ay).fill('#fff').stroke({ color: ACC, width: 2.4 });
      var mx = (Gx + px) / 2, my = (Gy + Ay) / 2;
      var off = isLeft ? -0.62 * s : 0.62 * s;
      T(liveG, 'a', mx + off, my - 0.05 * s, { size: LBL, fill: ACC });
      T(liveG, two ? (isLeft ? 'β′' : 'β') : 'β', px + (isLeft ? -0.2 * s : 0.2 * s), Ay + 0.55 * s, { size: LBL });
    });
  }

  T(liveG, 'α', Ax - 0.44 * s, Ay + 0.44 * s, { size: LBL });
  T(liveG, 'γ', Gx, Gy - 0.54 * s, { size: LBL });
  T(liveG, 'b', (Ax + Gx) / 2 - 0.32 * s, (Ay + Gy) / 2 - 0.44 * s, { size: LBL });

  var capParts;
  if (ci === 0) capParts = [['No triangle:  ', 0], ['a', 1], [' < ', 0], ['h', 1], ['      ', 0], ['a', 1], [' = ' + a.toFixed(1) + ',   ', 0], ['h', 1], [' = ', 0], ['b', 1], [' sin α = ' + HLEN.toFixed(2), 0]];
  else if (ci === 1) capParts = [['One right triangle:  ', 0], ['a', 1], [' = ', 0], ['h', 1], [' = ' + HLEN.toFixed(2), 0]];
  else if (ci === 2) capParts = [['Two triangles (ambiguous case):  ', 0], ['h', 1], [' < ', 0], ['a', 1], [' < ', 0], ['b', 1], ['      ', 0], [HLEN.toFixed(2) + ' < ' + a.toFixed(1) + ' < ' + BLEN.toFixed(0), 0]];
  else capParts = [['One triangle:  ', 0], ['a', 1], [' ≥ ', 0], ['b', 1], ['      ', 0], ['a', 1], [' = ' + a.toFixed(1) + ',   ', 0], ['b', 1], [' = ' + BLEN.toFixed(0), 0]];
  mixed(liveG, capParts, VW / 2, VH - capH / 2, Math.max(17, 0.55 * s), '#222');
}

/* ================= render / layout ================= */
function updateViewbox(w, h) {
  if (!w || !h) { w = container.clientWidth || 900; h = container.clientHeight || 700; }
  var ar = (w / h) || 1.4;
  VH = Math.max(320, Math.min(2400, VW / ar));
  draw.viewbox(0, 0, VW, VH);
}

function render() {
  casesG.clear(); liveG.clear();
  if (S.view === 'cases') renderCases(); else renderLive();
  var bc = document.getElementById('viewCasesBtn'), bv = document.getElementById('viewLiveBtn');
  if (bc) bc.classList.toggle('active', S.view === 'cases');
  if (bv) bv.classList.toggle('active', S.view === 'live');
}

document.addEventListener('fig-resize', function (e) {
  updateViewbox(e.detail.width, e.detail.height);
  render();
});

